// Cloudflare Worker entry (wrangler `main`): the OpenNext build of the Next.js
// app, plus the Cron Trigger handler in ./handlers.ts, wrapped by Sentry
// (./sentry.ts).

import * as Sentry from "@sentry/cloudflare";
import { WorkerEntrypoint } from "cloudflare:workers";
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so it is
// missing before a build (ts-expect-error would then fail after one).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNextWorker from "../.open-next/worker.js";
import { forEdge } from "./edge-cache";
import { createWorker, type FetchHandler } from "./handlers";
import { sentryOptions } from "./sentry";

/**
 * The pages Cloudflare's cache sits in front of (wrangler.jsonc "exports"): a hit is
 * answered without running this code. The default entrypoint sends only cacheable
 * requests here (worker/edge-cache.ts).
 */
export class CachedPages extends WorkerEntrypoint<CloudflareEnv> {
  async fetch(request: Request): Promise<Response> {
    const app = openNextWorker as FetchHandler;
    return forEdge(request, await app.fetch(request, this.env, this.ctx));
  }
}

export default Sentry.withSentry((env: CloudflareEnv) => sentryOptions(env), createWorker(openNextWorker as FetchHandler));
